import { Request, Response } from 'express';
import { RoleGuard } from './role-guard';

const adminPermissions = ['admin', 'view-admin-records'];
const userPermissions = ['read', 'write'];

class Permissions {
    public static hasPermission(req: Request, res: Response, next: Function) {
        const userRole = req.user.role;
        if (req.method === 'OPTIONS') {
            return next();
        }

        // Check if the requested resource matches any of the allowed permissions for the current role
        switch (req.path) {
            case '/api/admin':
                if (userRole.includes('admin')) {
                    return next();
                }
                break;

            case '/api/user/:id':
                if (userRole.includes('read') && userPermissions.includes(req.params.id)) {
                    return next();
                }
                break;

            default:
                return next(new Error(`Unauthorized access to ${req.path}`));
        }
    }
}

export function createApp() {
    const app = express();

    // Apply the role guard middleware
    app.use(RoleGuard(permissions));

    // Your other routes go here

    return app;
}
```

